/*
 * The player's ROM in RAM: loading, the SHA-1 check and relocation
 * (port/dsi/PLAN.md, "ROM loading and relocation at boot").
 */

#include <nds.h>
#include <fat.h>
#include <nds/arm9/exceptions.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "dsi.h"

// rom_relocs.s, generated by port/dsi/tools/gen_link.py. The offset lists are
// byte deltas in halfwords; 0 escapes a 32-bit delta.
extern const uint32_t gRomRelocAddCount;
extern const uint32_t gRomRelocSymbolCount;
extern const uint32_t gRomRelocKeptCount;
extern const uint32_t gRomRelocSymbols[]; // (offset, value) pairs
extern const uint16_t gRomRelocAdds[], gRomRelocAddsEnd[];
extern const uint16_t gRomRelocKept[], gRomRelocKeptEnd[];

#define ROM_FILE_SIZE 0x1000000
#define ROM_CHUNK 0x20000
#define EWRAM_BASE 0x02000000u
#define EWRAM_SIZE 0x40000u
#define IWRAM_BASE 0x03000000u

// The DSi SD slot first; DLDI (fat:) for flashcards and melonDS tests. The
// boot log goes next to the ROM.
static const char* const sRomPaths[] = { "sd:/tmc/baserom.gba", "fat:/tmc/baserom.gba" };
static const char* const sLogPaths[] = { "sd:/tmc/boot.txt", "fat:/tmc/boot.txt" };
static const char* const sSavePaths[] = { "sd:/tmc/tmc.sav", "fat:/tmc/tmc.sav" };
static const char* sSavePath;

const char* DsiSavePath(void) {
    return sSavePath;
}

// The USA ROM, as port/README.md.
static const uint8_t sUsaSha1[20] = {
    0xb4, 0xbd, 0x50, 0xe4, 0x13, 0x1b, 0x02, 0x7c, 0x33, 0x45,
    0x47, 0xb4, 0x52, 0x4e, 0x2d, 0xbb, 0xd4, 0x22, 0x71, 0x30,
};

static void HexDigest(char* out, const uint8_t* digest) {
    for (int i = 0; i < 20; i++) {
        sprintf(out + 2 * i, "%02x", digest[i]);
    }
}

static FILE* OpenRom(const char** path) {
    for (size_t i = 0; i < sizeof(sRomPaths) / sizeof(sRomPaths[0]); i++) {
        FILE* file = fopen(sRomPaths[i], "rb");
        if (file != NULL) {
            *path = sRomPaths[i];
            sSavePath = sSavePaths[i];
            DsiLogToFile(sLogPaths[i]);
            return file;
        }
    }
    return NULL;
}

/*
 * One pass over the file: the bytes the copy holds are read straight into it,
 * the rest into a scratch buffer, and all of it is hashed (sha1.c).
 */
bool DsiRomLoad(void) {
    uint32_t copySize = __rom_copy_end - __rom_copy;
    uint32_t readTicks = 0, hashTicks = 0, total;
    DsiSha1 sha;
    uint8_t digest[20];
    char hex[41];
    const char* path;
    uint8_t* scratch;
    FILE* file;
    long size;

    if (!fatInitDefault()) {
        DsiLog("no SD card or DLDI device (fatInitDefault failed)\n");
        return false;
    }
    file = OpenRom(&path);
    if (file == NULL) {
        DsiLog("no ROM: put your USA ROM at sd:/tmc/baserom.gba\n");
        DsiLogToDefaultFile();
        return false;
    }
    fseek(file, 0, SEEK_END);
    size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (size != ROM_FILE_SIZE) {
        DsiLog("%s is %ld bytes, expected %d\n", path, size, ROM_FILE_SIZE);
        fclose(file);
        return false;
    }
    scratch = malloc(ROM_CHUNK);
    if (scratch == NULL) {
        DsiLog("no memory for the read buffer\n");
        fclose(file);
        return false;
    }
    setvbuf(file, NULL, _IONBF, 0);

    DsiSha1Init(&sha);
    cpuStartTiming(0);
    for (uint32_t pos = 0; pos < ROM_FILE_SIZE;) {
        uint32_t length = ROM_FILE_SIZE - pos;
        uint8_t* dest = scratch;
        uint32_t t0, t1;

        if (length > ROM_CHUNK) {
            length = ROM_CHUNK;
        }
        if (pos < copySize) {
            dest = __rom_copy + pos;
            if (length > copySize - pos) {
                length = copySize - pos;
            }
        }
        t0 = cpuGetTiming();
        if (fread(dest, 1, length, file) != length) {
            DsiLog("read error at 0x%06lx in %s\n", (unsigned long)pos, path);
            cpuEndTiming();
            free(scratch);
            fclose(file);
            return false;
        }
        t1 = cpuGetTiming();
        DsiSha1Update(&sha, dest, length);
        readTicks += t1 - t0;
        hashTicks += cpuGetTiming() - t1;
        pos += length;
    }
    total = cpuEndTiming();
    DsiSha1Final(&sha, digest);
    free(scratch);
    fclose(file);

    HexDigest(hex, digest);
    DsiLog("read %d bytes from %s in %lu ms (read %lu, SHA-1 %lu)\n", ROM_FILE_SIZE, path,
           (unsigned long)timerTicks2msec(total), (unsigned long)timerTicks2msec(readTicks),
           (unsigned long)timerTicks2msec(hashTicks));
    DsiLog("SHA-1 %s\n", hex);
    DsiLogFlush();
    if (memcmp(digest, sUsaSha1, sizeof(digest)) != 0) {
        HexDigest(hex, sUsaSha1);
        DsiLog("not the USA ROM: expected %s\n", hex);
        return false;
    }
    return true;
}

// Pointer words in data objects need not be word-aligned (data is 2-aligned).
static inline uint32_t LoadWord(const uint8_t* p) {
    uint32_t value;
    memcpy(&value, p, 4);
    return value;
}

static inline void StoreWord(uint8_t* p, uint32_t value) {
    memcpy(p, &value, 4);
}

// The next offset from a delta list, or false at its end.
static bool NextOffset(const uint16_t** p, const uint16_t* end, uint32_t* offset) {
    uint32_t step;

    if (*p >= end) {
        return false;
    }
    step = *(*p)++;
    if (step == 0) {
        step = (*p)[0] | ((uint32_t)(*p)[1] << 16);
        *p += 2;
    }
    *offset += step;
    return true;
}

/*
 * Each word is checked before it changes: it must hold the kind of GBA address
 * the generator found there, which the right ROM guarantees.
 */
bool DsiRomRelocate(void) {
    uint8_t* copy = __rom_copy;
    uint32_t size = __rom_copy_end - __rom_copy;
    uint32_t delta = (uint32_t)copy - DSI_ROM_BASE;
    uint32_t adds = 0, symbols = 0, kept = 0, unexpected = 0, offset;
    const uint16_t* p;

    p = gRomRelocAdds;
    offset = 0;
    while (NextOffset(&p, gRomRelocAddsEnd, &offset)) {
        uint32_t value;

        if (offset > size - 4) {
            DsiLog("relocation at 0x%06lx is outside the copy\n", (unsigned long)offset);
            return false;
        }
        value = LoadWord(copy + offset);
        if (value - DSI_ROM_BASE >= size) {
            unexpected++;
        }
        StoreWord(copy + offset, value + delta);
        adds++;
    }
    for (uint32_t i = 0; i < gRomRelocSymbolCount; i++) {
        uint32_t value = LoadWord(copy + gRomRelocSymbols[2 * i]);
        uint32_t region = value >> 24;

        // ROM, IWRAM, or a raw GBA hardware address (into its shadow).
        if (region != 0x08 && region != 0x09 && region != IWRAM_BASE >> 24 && (region < 0x04 || region > 0x07)) {
            unexpected++;
        }
        StoreWord(copy + gRomRelocSymbols[2 * i], gRomRelocSymbols[2 * i + 1]);
        symbols++;
    }
    p = gRomRelocKept;
    offset = 0;
    while (NextOffset(&p, gRomRelocKeptEnd, &offset)) {
        if (LoadWord(copy + offset) - EWRAM_BASE >= EWRAM_SIZE) {
            unexpected++;
        }
        kept++;
    }
    DC_FlushRange(copy, size);

    DsiLog("relocated: %lu add-base, %lu symbol; %lu EWRAM kept; %lu unexpected\n", (unsigned long)adds,
           (unsigned long)symbols, (unsigned long)kept, (unsigned long)unexpected);
    DsiLogFlush();
    if (adds != gRomRelocAddCount || kept != gRomRelocKeptCount) {
        DsiLog("expected %lu add-base and %lu EWRAM\n", (unsigned long)gRomRelocAddCount,
               (unsigned long)gRomRelocKeptCount);
        return false;
    }
    return unexpected == 0;
}

// The registers BlocksDS saved, into the log; PC is as saved (a data abort is
// 8 bytes past the faulting instruction, 4 in Thumb).
static void Exception(void) {
    const uint32_t* r = (const uint32_t*)exceptionRegisters;

    DsiLog("exception: pc %08lx lr %08lx sp %08lx\n", (unsigned long)r[15], (unsigned long)r[14],
           (unsigned long)r[13]);
    DsiFatal("r0 %08lx r1 %08lx r2 %08lx r3 %08lx", (unsigned long)r[0], (unsigned long)r[1],
             (unsigned long)r[2], (unsigned long)r[3]);
}

/*
 * Stray GBA ROM pointers must fault: on the DSi the GBA slot reads back 0xFF.
 * BlocksDS leaves 0x08000000-0x0AFFFFFF out of every MPU region, so an access
 * there is an abort; a region found over it is switched off.
 */
void DsiProtectGbaSlot(void) {
    static const uint32_t probes[] = { 0x08000000, 0x09000000, 0x0A000000, 0x0AFFFFFC };

    for (size_t i = 0; i < sizeof(probes) / sizeof(probes[0]); i++) {
        int region = mpuRegionGet(probes[i]);
        if (region >= 0) {
            DsiLog("MPU region %d (%08lx) covers 0x%08lx: off\n", region, (unsigned long)CP15_GetRegion(region),
                   (unsigned long)probes[i]);
            CP15_SetRegion(region, 0);
        }
    }
    setExceptionHandler(Exception);
    DsiLog("GBA slot unmapped (MPU)\n");
}
